import{_ as i,a0 as l,w as m,s as o,I as p,x as n,a1 as t,A as r,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"Linux有問必答：如何在Linux下重命名多個文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在Linux下重命名多個文件 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在Linux下重命名多個文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在Linux下重命名多個文件 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141224 Linux FAQs with Answers--How to rename multiple files on Linux","title":"Linux有問必答：如何在Linux下重命名多個文件","tag":"201502","desc":""},"relativePath":"201502/20141224 Linux FAQs with Answers--How to rename multiple files on Linux.md","filePath":"[post].md"}'),d={name:"201502/20141224 Linux FAQs with Answers--How to rename multiple files on Linux.md"};function g(u,e,x,j,_,f){const a=l("Link");return m(),o("div",null,[e[14]||(e[14]=p("h1",{id:"linux有問必答-如何在linux下重命名多個文件",tabindex:"-1"},[n("Linux有問必答：如何在Linux下重命名多個文件 "),p("a",{class:"header-anchor",href:"#linux有問必答-如何在linux下重命名多個文件","aria-label":"Permalink to “Linux有問必答：如何在Linux下重命名多個文件”"},"​")],-1)),e[15]||(e[15]=p("blockquote",null,[p("p",null,[p("strong",null,"提問"),n("：我知道我可以用mv命令重命名文件。但是當我想重命名很多文件怎麼辦？如果為每個文件都這麼做將會是很乏味的。有沒有辦法一次性重命名多個文件？")])],-1)),p("p",null,[e[1]||(e[1]=n("在Linux中，當你想要改變一個文件名，使用mv命令就好了。然而mv不能使用通配符重命名多個文件。可以用sed、awk或者與",-1)),t(a,{href:"http://xmodulo.com/xargs-command-linux.html"},{default:r(()=>[...e[0]||(e[0]=[n("xargs",-1)])]),_:1}),e[2]||(e[2]=n("結合使用來處理多個文件的情況。然而，這些命令列即繁瑣又不友好，並且如果不小心的話還很容易出錯。你不會想要撤銷1000個文件的錯誤名吧！",-1))]),e[16]||(e[16]=s(`<p>當你想要重命名多個文件的時候，rename 工具或許是最簡單、最安全和最強大的命令列工具。這個rename命令實際上是一個Perl腳本，它預安裝在所有的現在Linux發行版上。</p><p>下面是重命名命令的基本語法。</p><pre><code>rename [-v -n -f] &lt;pcre&gt; &lt;files&gt;
</code></pre><p>&lt;pcre&gt; 是Perl兼容正則表達式，它表示的是要重命名的文件和該怎麼做。正則表達式的形式是‘s/old-name/new-name/’。</p><p>‘-v’選項會顯示文件名改變的細節（比如：XXX重命名成YYY）。</p><p>‘-n’選項告訴rename命令在不實際改變名稱的情況下顯示文件將會重命名的情況。這個選項在你想要在不改變文件名的情況下模擬改變文件名的情況下很有用。</p><p>‘-f’選項強制覆蓋存在的文件。</p><p>下面，就讓我們看下rename命令的幾個實際例子。</p><h3 id="改變文件擴展名" tabindex="-1">改變文件擴展名 <a class="header-anchor" href="#改變文件擴展名" aria-label="Permalink to “改變文件擴展名”">​</a></h3><p>假設你有許多.jpeg的圖片文件。你想要把它們的名字改成<em>.jpg。下面的命令就會將</em>.jpeg 文件改成 *.jpg。</p><pre><code>$ rename &#39;s/\\.jpeg$/\\.jpg/&#39; *.jpeg 
</code></pre><h3 id="大寫改成小寫-反之亦然" tabindex="-1">大寫改成小寫，反之亦然 <a class="header-anchor" href="#大寫改成小寫-反之亦然" aria-label="Permalink to “大寫改成小寫，反之亦然”">​</a></h3><p>有時你想要改變文件名的大小寫，你可以使用下面的命令。</p><p>把所有的文件改成小寫：</p><pre><code># rename &#39;y/A-Z/a-z/&#39; *
</code></pre><p>把所有的文件改成大寫：</p><pre><code># rename &#39;y/a-z/A-Z/&#39; * 
</code></pre><p><img src="https://farm9.staticflickr.com/8655/16054304245_bcf9d23b59_b.jpg" alt=""></p><h3 id="更改文件名模式" tabindex="-1">更改文件名模式 <a class="header-anchor" href="#更改文件名模式" aria-label="Permalink to “更改文件名模式”">​</a></h3><p>現在讓我們考慮更復雜的包含子模式的正則表達式。在PCRE中，子模式包含在圓括號中，$符後接上數字（比如$1，$2）。</p><p>比如，下面的命令會將‘img_NNNN.jpeg’變成‘dan_NNNN.jpg’。</p><pre><code># rename -v &#39;s/img_(\\d{4})\\.jpeg$/dan_$1\\.jpg/&#39; *.jpeg
</code></pre><hr><pre><code>img_5417.jpeg renamed as dan_5417.jpg
img_5418.jpeg renamed as dan_5418.jpg
img_5419.jpeg renamed as dan_5419.jpg
img_5420.jpeg renamed as dan_5420.jpg
img_5421.jpeg renamed as dan_5421.jpg
</code></pre><p>比如，下面的命令會將‘img_000NNNN.jpeg’變成‘dan_NNNN.jpg’。</p><pre><code># rename -v &#39;s/img_\\d{3}(\\d{4})\\.jpeg$/dan_$1\\.jpg/&#39; *jpeg
</code></pre><hr><pre><code>img_0005417.jpeg renamed as dan_5417.jpg
img_0005418.jpeg renamed as dan_5418.jpg
img_0005419.jpeg renamed as dan_5419.jpg
img_0005420.jpeg renamed as dan_5420.jpg
img_0005421.jpeg renamed as dan_5421.jpg
</code></pre><p>上面的例子中，子模式‘\\d{4}’會捕捉4個連續的數字，捕捉的四個數字就是$1, 將會用於新的文件名。</p><hr>`,30)),p("p",null,[e[4]||(e[4]=n("via: ",-1)),t(a,{href:"http://ask.xmodulo.com/rename-multiple-files-linux.html"},{default:r(()=>[...e[3]||(e[3]=[n("http://ask.xmodulo.com/rename-multiple-files-linux.html",-1)])]),_:1})]),p("p",null,[e[7]||(e[7]=n("譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:r(()=>[...e[5]||(e[5]=[n("geekpi",-1)])]),_:1}),e[8]||(e[8]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[6]||(e[6]=[n("wxy",-1)])]),_:1})]),p("p",null,[e[11]||(e[11]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[n("LCTT",-1)])]),_:1}),e[12]||(e[12]=n(" 原創翻譯，",-1)),t(a,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[n("Linux中國",-1)])]),_:1}),e[13]||(e[13]=n(" 榮譽推出",-1))])])}const h=i(d,[["render",g]]);export{N as __pageData,h as default};
